#include "pal_mdns.h"

#include <string.h>
#include "mdns.h"
#include "esp_log.h"

static const char *TAG = "pal_mdns";

int pal_mdns_init(const char *hostname) {
    if (!hostname) return -1;

    esp_err_t err = mdns_init();
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "mDNS init failed: %s", esp_err_to_name(err));
        return -1;
    }

    mdns_hostname_set(hostname);
    mdns_instance_name_set(hostname);

    ESP_LOGI(TAG, "mDNS initialized: %s.local", hostname);
    return 0;
}

int pal_mdns_register_service(const char *service_type, const char *instance, uint16_t port) {
    if (!service_type || !instance) return -1;

    char proto[16] = "_tcp";
    char type[64];

    const char *dot = strrchr(service_type, '.');
    if (dot) {
        size_t type_len = dot - service_type;
        if (type_len >= sizeof(type)) type_len = sizeof(type) - 1;
        strncpy(type, service_type, type_len);
        type[type_len] = '\0';
        strncpy(proto, dot + 1, sizeof(proto) - 1);
    } else {
        strncpy(type, service_type, sizeof(type) - 1);
    }

    esp_err_t err = mdns_service_add(instance, type, proto, port, NULL, 0);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Service add failed: %s", esp_err_to_name(err));
        return -1;
    }

    ESP_LOGI(TAG, "Registered service %s.%s port %u", type, proto, port);
    return 0;
}

int pal_mdns_resolve(const char *hostname, pal_mdns_result_t *result, uint32_t timeout_ms) {
    if (!hostname || !result) return -1;

    memset(result, 0, sizeof(*result));

    esp_ip4_addr_t addr = {0};
    esp_err_t err = mdns_query_a(hostname, timeout_ms, &addr);
    if (err != ESP_OK) {
        ESP_LOGW(TAG, "Resolve %s failed", hostname);
        return -1;
    }

    strncpy(result->hostname, hostname, sizeof(result->hostname) - 1);
    snprintf(result->addr, sizeof(result->addr), IPSTR, IP2STR(&addr));
    result->port = 0;

    ESP_LOGI(TAG, "Resolved %s -> %s", hostname, result->addr);
    return 0;
}

int pal_mdns_query_service(const char *service_type, pal_mdns_result_t *results,
                           size_t max_results, uint32_t timeout_ms) {
    if (!service_type || !results || max_results == 0) return -1;

    char proto[16] = "_tcp";
    char type[64];

    const char *dot = strrchr(service_type, '.');
    if (dot) {
        size_t type_len = dot - service_type;
        if (type_len >= sizeof(type)) type_len = sizeof(type) - 1;
        strncpy(type, service_type, type_len);
        type[type_len] = '\0';
        strncpy(proto, dot + 1, sizeof(proto) - 1);
    } else {
        strncpy(type, service_type, sizeof(type) - 1);
    }

    mdns_result_t *mdns_results = NULL;
    esp_err_t err = mdns_query_ptr(type, proto, timeout_ms, (int)max_results, &mdns_results);
    if (err != ESP_OK || !mdns_results) return 0;

    int count = 0;
    mdns_result_t *r = mdns_results;
    while (r && count < (int)max_results) {
        if (r->hostname) {
            strncpy(results[count].hostname, r->hostname, sizeof(results[count].hostname) - 1);
        }
        if (r->addr && r->addr->addr.type == ESP_IPADDR_TYPE_V4) {
            snprintf(results[count].addr, sizeof(results[count].addr),
                     IPSTR, IP2STR(&r->addr->addr.u_addr.ip4));
        }
        results[count].port = r->port;
        count++;
        r = r->next;
    }

    mdns_query_results_free(mdns_results);
    return count;
}

void pal_mdns_deinit(void) {
    mdns_free();
}